mapper.select:
SELECT ti.id, ti.code, ti.source_code, ti.transfer_direction, ti.approve_status, ti.invalid_status, ti.bill_date, ti.out_warehouse_id, ti.out_warehouse_name, ti.in_warehouse_id, ti.in_warehouse_name, ti.approve_user_name, ti.create_user_name, ti.create_time, tid.sku_id, tid.sku_no, tid.qty, tid.out_warehouse_location, tid.remark, tid.plan_qty, tid.source_detail_id FROM transfer_in ti INNER JOIN transfer_in_detail tid ON ti.id=tid.main_id AND tid.is_deleted=FALSE WHERE ti.is_deleted=FALSE
AND tid.sku_no IN
#{skuNo}
AND ti.code ILIKE concat('%', #{params.code} ,'%')
AND ti.approve_status IN
#{approveStatus}
AND ti.invalid_status =#{params.invalidStatus}
AND ti.transfer_direction =#{params.transferDirection}
AND ti.out_warehouse_id IN
#{warehouseId}
AND ti.in_warehouse_id IN
#{warehouseId}
AND ti.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ti.create_time
AND ti.create_user_id IN
#{createUserId}
AND ti.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ti.bill_date
${params.permissionSql}
ORDER BY ti.create_time DESC
